import{_ as p,a0 as s,w as e,s as d,ao as r,I as l,x as i,a1 as u,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"5 个最具生产力的 Linux 发行版 | LCTT x X-CMD","titleTemplate":false,"description":"5 个最具生产力的 Linux 发行版 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 个最具生产力的 Linux 发行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 个最具生产力的 Linux 发行版 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190111 Top 5 Linux Distributions for Productivity","title":"5 个最具生产力的 Linux 发行版","tag":"201906","desc":""},"relativePath":"201906/20190111 Top 5 Linux Distributions for Productivity.md","filePath":"[post].md"}'),f={name:"201906/20190111 Top 5 Linux Distributions for Productivity.md"};function m(a,t,b,S,x,T){const n=s("Link");return e(),d("div",null,[t[43]||(t[43]=r('<h1 id="_5-个最具生产力的-linux-发行版" tabindex="-1">5 个最具生产力的 Linux 发行版 <a class="header-anchor" href="#_5-个最具生产力的-linux-发行版" aria-label="Permalink to “5 个最具生产力的 Linux 发行版”">​</a></h1><blockquote><p>如果你正在寻找一个适合开发工作的完美环境，我敢说你找不到比 Pop!_OS 更好的选择。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/productivity_main.jpg?itok=2IKyg_7_" alt=""></p><p>必须承认的是，这样的一个热门话题其实很难被总结的话题。为什么呢？首先，Linux 在就是一种有生产力的操作系统。由于它极强的可靠性和稳定的平台，使得完成工作变得很容易。其次为了衡量工作的效率，你需要考虑到哪项工作需要得到生产力方面的助推。是日常办公？开发类工作？学校事务？数据挖掘？或者是人力资源？你可以看到这个问题有多复杂。</p><p>然而，这并不意味着某些发行版无法更好地配置将底层操作系统呈现为一个有效的平台来完成工作。恰恰相反，许多发行版在偏离生产力这条道路上越走越远，所以你不会意识到你自己处在工作的窘境中，而是继续挖掘自己的潜力在工期结束之前拼命赶上进度。这些 Linux 发行版可以帮助你化繁为简，因此或许可以减少你工作流程中的痛点。</p><p>让我们来看一下这些发行版并为你找出适合你的最佳选择。为了更具条理，我按照生产力诉求把它们分成了几类。这项任务本身也是一种挑战，因为每个人在生产力提升上的需要是千差万别的。然而，我所关注的是下列的几项：</p><ul><li>常规：适于那些只需要有效地完成多项工作的人。</li><li>设计：适于那些从事设计创造和图像处理的人。</li><li>开发：适于那些使用 Linux 桌面发行版来进行编程工作的人。</li><li>运维：适于那些需要一个发行版来促进其执行系统管理任务的人。</li><li>教育：适于那些需要桌面发行版可以助力他们在教育领域更高效的人。</li></ul><p>诚然，有很多很多类别的发行版可供挑选，其中的很多可能用起来十分得心应手，但这五种或许是你最为需要的。</p><h3 id="常规" tabindex="-1">常规 <a class="header-anchor" href="#常规" aria-label="Permalink to “常规”">​</a></h3>',9)),l("p",null,[t[1]||(t[1]=i("对于常规的生产力诉求来说，你不会找到比 ",-1)),u(n,{href:"https://www.ubuntu.com/"},{default:o(()=>[...t[0]||(t[0]=[i("Ubuntu",-1)])]),_:1}),t[2]||(t[2]=i(" 更为高效的了。在这个类别中首推 Ubuntu 最主要的原因是因为它实现了桌面操作系统、软件、服务的无缝集成。你可能会问为什么我不选择同类别的 Linux Mint 呢？因为 Ubuntu 现在默认的的桌面环境为 GNOME 桌面，而它拥有 GNOME 许多扩展程序的优势的加成（图 1）。",-1))]),t[44]||(t[44]=l("p",null,[l("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/productivity_1.jpg?itok=yxez3X1w",alt:"GNOME Clipboard",title:"GNOME Clipboard"})],-1)),t[45]||(t[45]=l("p",null,[l("em",null,"图 1：运行中的 GNOME 桌面的剪切板管理工具。")],-1)),t[46]||(t[46]=l("p",null,"这些扩展程序在提升生产力方面做了很多努力（所以 Ubuntu 比 Linux Mint 获得了更多的认可）。但是 Ubuntu 不仅仅是装了一个普通的 GNOME 桌面。事实上，他们致力于将它改进的更为轻量化、更为高效、以及用户友好度更高、开箱即用。总而言之，由于 Ubuntu 正确的融合了多种特性，开箱即用，完善的软件支持（仅对工作方面而言），这些特性使它几乎成为了生产力领域最为完美的一个平台。",-1)),t[47]||(t[47]=l("p",null,"不管你是要写一篇文档，制作一张电子表格，写一个新的软件，开发公司的网站，设计商用的图形，管理一个服务器或是网络，抑或是在你的公司内从事人力资源管理工作，Ubuntu 都可以满足你的需求。Ubuntu 桌面发行版也并不要求你耗费很大的精力才能开始开始开展工作……它直接就能使用（并且工作的十分优秀）。最后，得益于它是基于 Debian 的，使得在 Ubuntu 上安装第三方的软件十分简便。",-1)),t[48]||(t[48]=l("p",null,"很难不支持这一发行版独占生产力发行版列表的鳌头，尽管 Ubuntu 几乎已经成为几乎所有“某某类顶级发行版”列表的榜首。",-1)),t[49]||(t[49]=l("h3",{id:"设计",tabindex:"-1"},[i("设计 "),l("a",{class:"header-anchor",href:"#设计","aria-label":"Permalink to “设计”"},"​")],-1)),l("p",null,[t[4]||(t[4]=i("如果你正在寻求提升你的平面设计效率，你不能错过 ",-1)),u(n,{href:"https://labs.fedoraproject.org/en/design-suite/"},{default:o(()=>[...t[3]||(t[3]=[i("Fedora 设计套件",-1)])]),_:1}),t[5]||(t[5]=i("。这一 Fedora 衍生版是由负责 Fedora 相关的艺术作品的团队亲自操刀制作的。虽然其默认选择的应用程序并不是一个庞大的工具集合，但它所包含的工具都是创建和处理图像专用的。",-1))]),l("p",null,[t[7]||(t[7]=i("有了 GIMP、Inkscape、Darktable、Krita、Entangle、Blender、Pitivi、Scribus 等应用程序（图 2），你可以找到完成图像编辑工作所需要的一切。但是 Fedora 设计套件并不仅限于此。这个桌面平台还包括一堆教程，涵盖了许多已安装的应用程序。对于任何想要尽可能提高效率的人来说，这将是一些非常有用的信息。不过，我要说的是，GNOME 收藏夹中的教程并没有超乎",-1)),u(n,{href:"https://fedoraproject.org/wiki/Design_Suite/Tutorials"},{default:o(()=>[...t[6]||(t[6]=[i("此页中",-1)])]),_:1}),t[8]||(t[8]=i("链接的内容。",-1))]),t[50]||(t[50]=l("p",null,[l("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/productivity_2.jpg?itok=ke0b8qyH",alt:"Fedora Design Suite Favorites",title:"Fedora Design Suite Favorites"})],-1)),t[51]||(t[51]=l("p",null,[l("em",null,"图 2：Fedora 设计套件收藏夹菜单包含了许多工具，可以让你用于图形设计。")],-1)),t[52]||(t[52]=l("p",null,"那些使用数码相机的用户肯定会喜欢 Entangle 应用程序，它可以让你在电脑上控制单反相机。",-1)),t[53]||(t[53]=l("h3",{id:"开发",tabindex:"-1"},[i("开发 "),l("a",{class:"header-anchor",href:"#开发","aria-label":"Permalink to “开发”"},"​")],-1)),l("p",null,[t[11]||(t[11]=i("几乎所有的 Linux 发行版都是程序员的绝佳平台。然而，有一种特定的发行版脱颖而出，并超越了其他发行版，它将是你见过的用于编程类最有效率的工具之一。这个操作系统来自 ",-1)),u(n,{href:"https://system76.com/"},{default:o(()=>[...t[9]||(t[9]=[i("System76",-1)])]),_:1}),t[12]||(t[12]=i("（LCTT 译注：一家美国的计算机制造商），名为 ",-1)),u(n,{href:"https://system76.com/pop"},{default:o(()=>[...t[10]||(t[10]=[i("Pop!_OS",-1)])]),_:1}),t[13]||(t[13]=i("。Pop!_OS 是专门为创作者定制的，但不是针对艺术类。相反，Pop!_OS 面向专门从事开发、编程和软件制作的程序员。如果你需要一个既能完美的胜任开发工作又包含符合使用习惯的桌面操作系统的开发环境，Pop!_OS 将会是你的不二选择。（图 3）",-1))]),l("p",null,[t[15]||(t[15]=i("可能会让你感到惊讶（考虑到这个操作系统是多么“年轻”）的是 Pop!_OS 也是你将使用的基于 GNOME 平台的最稳定系统的之一。这意味着 Pop!_OS 不只是为创作者和创客准备的，也是为任何想要一个可靠的操作系统的人准备的。你可以下载针对你的硬件的专门 ISO 文件，这一点是许多用户十分欣赏的。如果你有英特尔硬件，",-1)),u(n,{href:"https://system76.com/pop"},{default:o(()=>[...t[14]||(t[14]=[i("下载",-1)])]),_:1}),t[16]||(t[16]=i(" Intel 或 AMD 的版本。如果你的显卡是 NVIDIA，请下载该特定版本。不管怎样，你肯定会得到针对不同平台进行特殊定制的稳定版本。",-1))]),t[54]||(t[54]=l("p",null,[l("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/productivity_3_0.jpg?itok=8UkCUfsD",alt:"Pop!_OS",title:"Pop!_OS"})],-1)),t[55]||(t[55]=l("p",null,[l("em",null,"图 3：装有 GNOME 桌面的 Pop!_OS 一览。")],-1)),t[56]||(t[56]=l("p",null,"有趣的是，在 Pop!_OS 中，你不会找到太多预装的开发工具。你也不会找到 IDE 或许多其他开发工具。但是，你可以在 Pop 商店中中找到所需的所有开发工具。",-1)),t[57]||(t[57]=l("h3",{id:"运维",tabindex:"-1"},[i("运维 "),l("a",{class:"header-anchor",href:"#运维","aria-label":"Permalink to “运维”"},"​")],-1)),l("p",null,[t[18]||(t[18]=i("如果你正在寻找适合系统管理的最具生产力的发行版，",-1)),u(n,{href:"https://www.debian.org/"},{default:o(()=>[...t[17]||(t[17]=[i("Debian",-1)])]),_:1}),t[19]||(t[19]=i(" 将会是你的不二之选。为什么这么说呢？因为 Debian 不仅仅拥有无与伦比的可靠性，它也是众多能从苦海中将你解救出来的最好的一个发行版。Debian 是易用性和无限可能性的完美结合。最重要的是，因为它是许多其他发行版的基础，所以可以打赌，如果你需要一个任务的管理工具，那么它一定支持 Debian 系统。当然，我们讨论的是一般的系统管理任务，这意味着大多数时候你需要使用终端窗口 SSH 连接到服务器（图 4），或者在浏览器上使用网络上基于 web 的 GUI 工具。既然如此为什么还要使用一个增加复杂性的桌面呢（比如 Fedora 中的 SELinux 或 openSUSE 中的 YaST）呢？所以，应选择更为简洁易用的那一种。",-1))]),t[58]||(t[58]=l("p",null,[l("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/productivity_4.jpg?itok=c9yD3Xw2",alt:"Debian",title:"Debian"})],-1)),t[59]||(t[59]=l("p",null,[l("em",null,"图 4：在 Debian 系统上通过 SSH 连接到远程服务器。")],-1)),t[60]||(t[60]=l("p",null,"你可以选择你想要的不同的桌面（包括 GNOME、Xfce、KDE、Cinnamon、MATE、LXDE），可以确保你所使用的桌面外观最适合你的工作习惯。",-1)),t[61]||(t[61]=l("h3",{id:"教育",tabindex:"-1"},[i("教育 "),l("a",{class:"header-anchor",href:"#教育","aria-label":"Permalink to “教育”"},"​")],-1)),l("p",null,[t[21]||(t[21]=i("如果你是一名老师或学生，抑或是其他从事与教育相关工作的人士，你需要适当的工具来提高生产力。之前，有 Edubuntu 这样的版本。这一版本位列教育类相关发行版排名的前列。然而，自从 Ubuntu 14.04 版之后这一发行版就再也没有更新。还好，现在有一款基于 openSUSE 的新的以教育为基础的发行版有望夺摘得桂冠。这一改版叫做 ",-1)),u(n,{href:"https://en.opensuse.org/openSUSE:Education-Li-f-e"},{default:o(()=>[...t[20]||(t[20]=[i("openSUSE:Education-Li-f-e",-1)])]),_:1}),t[22]||(t[22]=i("（Li-f-e：Linux For Education - 图 5），它基于 openSUSE Leap 42.1 （所以它可能稍微有一点过时）。",-1))]),t[62]||(t[62]=r('<p>openSUSE:Education-Li-f-e 包含了以下工具：</p><ul><li>Brain Workshop（大脑工坊）：一种基于 dual n-back 模式的大脑训练软件（LCTT 译注：dual n-back 训练是一种科学的智力训练方法，可以改善人的工作记忆和流体智力）</li><li>GCompris：一种针对青少年的教育软件包</li><li>gElemental：一款元素周期表查看工具</li><li>iGNUit：一款通用的记忆卡片工具</li><li>Little Wizard：基于 Pascal 语言的少儿编程开发环境</li><li>Stellarium：天文模拟器</li><li>TuxMath：数学入门游戏</li><li>TuxPaint：一款少儿绘画软件</li><li>TuxType：一款为少儿准备的打字入门软件</li><li>wxMaxima：一个跨平台的计算机代数系统</li><li>Inkscape：矢量图形编辑软件</li><li>GIMP：图像处理软件（LCTT 译注：被誉为 Linux 上的 PhotoShop）</li><li>Pencil：GUI 模型制作工具</li><li>Hugin：全景照片拼接及 HDR 效果混合软件</li></ul><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/productivity_5.jpg?itok=oAFtV8nT" alt="Education" title="Education"></p><p><em>图 5：openSUSE:Education-Li-f-e 发行版拥有大量的工具可以帮你在学校中变得更为高效。</em></p>',4)),l("p",null,[t[25]||(t[25]=i("同时还集成在 openSUSE:Education-Li-f-e 中的还有 ",-1)),u(n,{href:"https://en.opensuse.org/Portal:KIWI-LTSP"},{default:o(()=>[...t[23]||(t[23]=[i("KIWI-LTSP Server",-1)])]),_:1}),t[26]||(t[26]=i(" 。KIWI-LTSP 服务器是一个灵活的、经济高效的解决方案，旨在使全世界的学校、企业和组织能够轻松地安装和部署桌面工作站。虽然这可能不会直接帮助学生变得更具生产力，但它肯定会使教育机构在部署供学生使用的桌面时更有效率。有关配置 KIWI-LTSP 的更多信息，请查看 openSUSE ",-1)),u(n,{href:"https://en.opensuse.org/SDB:KIWI-LTSP_quick_start"},{default:o(()=>[...t[24]||(t[24]=[i("KIWI-LTSP 快速入门指南",-1)])]),_:1}),t[27]||(t[27]=i("。",-1))]),t[63]||(t[63]=l("hr",null,null,-1)),l("p",null,[t[29]||(t[29]=i("via: ",-1)),u(n,{href:"https://www.linux.com/blog/learn/2019/1/top-5-linux-distributions-productivity"},{default:o(()=>[...t[28]||(t[28]=[i("https://www.linux.com/blog/learn/2019/1/top-5-linux-distributions-productivity",-1)])]),_:1})]),l("p",null,[t[34]||(t[34]=i("作者：",-1)),u(n,{href:"https://www.linux.com/users/jlwallen"},{default:o(()=>[...t[30]||(t[30]=[i("Jack Wallen",-1)])]),_:1}),t[35]||(t[35]=i(" 选题：",-1)),u(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[31]||(t[31]=[i("lujun9972",-1)])]),_:1}),t[36]||(t[36]=i(" 译者：",-1)),u(n,{href:"https://github.com/qfzy1233"},{default:o(()=>[...t[32]||(t[32]=[i("qfzy1233",-1)])]),_:1}),t[37]||(t[37]=i(" 校对：",-1)),u(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[33]||(t[33]=[i("wxy",-1)])]),_:1})]),l("p",null,[t[40]||(t[40]=i("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[38]||(t[38]=[i("LCTT",-1)])]),_:1}),t[41]||(t[41]=i(" 原创编译，",-1)),u(n,{href:"https://linux.cn/"},{default:o(()=>[...t[39]||(t[39]=[i("Linux中国",-1)])]),_:1}),t[42]||(t[42]=i(" 荣誉推出",-1))])])}const E=p(f,[["render",m]]);export{P as __pageData,E as default};
